#!/usr/bin/env node
/**
 * scaffold-woodpecker-ci.mjs - ecrit le pipeline Woodpecker CI standard d'un projet.
 *
 * Pourquoi : chaque projet NF porte un `.woodpecker.yml` dont l'en-tete annonce
 *   « Auto-generated by scripts/scaffold-woodpecker-ci.mjs ». Ce generateur n avait
 *   jamais ete commite (revendication de provenance fausse). Ce script le rend vrai :
 *   il reproduit le gabarit standard, ne l ecrit que s il est absent, et refuse
 *   d ecraser un pipeline personnalise sans --force.
 *
 * Usage (depuis la racine d un projet) :
 *   node scripts/scaffold-woodpecker-ci.mjs            ecrit si absent
 *   node scripts/scaffold-woodpecker-ci.mjs --check    sort 1 si absent ou different
 *   node scripts/scaffold-woodpecker-ci.mjs --force    ecrase
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const TARGET = join(process.cwd(), ".woodpecker.yml");
const force = process.argv.includes("--force");
const checkOnly = process.argv.includes("--check");

const TEMPLATE = `# Auto-generated by scripts/scaffold-woodpecker-ci.mjs - NF Woodpecker CI pipeline

# Run on push/PR/manual for the main branches.
when:
  event: [push, pull_request, manual]
  branch: [main, master, preview]

steps:
  validate:
    image: node:26
    commands:
      - npm install -g pnpm@12.8.1
      - pnpm install --frozen-lockfile
      - pnpm typecheck
      - pnpm lint
      - pnpm test

  build:
    image: node:26
    depends_on: [validate]
    commands:
      - npm install -g pnpm@12.8.1
      - pnpm build

`;

const current = existsSync(TARGET) ? readFileSync(TARGET, "utf8") : null;

if (checkOnly) {
  if (current !== TEMPLATE) {
    console.error(".woodpecker.yml absent ou different du gabarit NF.");
    process.exit(1);
  }
  console.log(".woodpecker.yml conforme au gabarit NF.");
  process.exit(0);
}

if (current === TEMPLATE) {
  console.log(".woodpecker.yml deja conforme.");
} else if (current === null) {
  writeFileSync(TARGET, TEMPLATE, "utf8");
  console.log(".woodpecker.yml cree.");
} else if (force) {
  writeFileSync(TARGET, TEMPLATE, "utf8");
  console.log(".woodpecker.yml ecrase (--force).");
} else {
  console.error(".woodpecker.yml existe et differe du gabarit ; relancer avec --force pour l ecraser.");
  process.exit(1);
}
